def tokenize_bpe(word: str, rules: list) -> list:
    symbols = list(word) + ["_"]
    for pair in rules:
        p1, p2 = pair
        merged = "".join(pair)
        new_symbols = []
        i = 0
        while i < len(symbols):
            if i < len(symbols) - 1 and symbols[i] == p1 and symbols[i + 1] == p2:
                new_symbols.append(merged)
                i += 2
            else:
                new_symbols.append(symbols[i])
                i += 1
        symbols = new_symbols
    return symbols

